    12	import type {ValidateLoginPageOnyxProps, ValidateLoginPageProps} from './types';
    13	
    14	function ValidateLoginPage({
    15	    account,
    16	    credentials,
    17	    route: {
    18	        params: {accountID, validateCode, exitTo},
    19	    },
    20	    session,
    21	}: ValidateLoginPageProps<ValidateLoginPageOnyxProps>) {
    22	    const login = credentials?.login;
    23	    const autoAuthState = session?.autoAuthState ?? CONST.AUTO_AUTH_STATE.NOT_STARTED;
    24	    const isSignedIn = !!session?.authToken && session?.authTokenType !== CONST.AUTH_TOKEN_TYPES.ANONYMOUS;
    25	    const is2FARequired = !!account?.requiresTwoFactorAuth;
    26	    const cachedAccountID = credentials?.accountID;
    27	
    28	    useEffect(() => {
    29	        if (!login && isSignedIn && (autoAuthState === CONST.AUTO_AUTH_STATE.SIGNING_IN || autoAuthState === CONST.AUTO_AUTH_STATE.JUST_SIGNED_IN)) {
    30	            // The user clicked the option to sign in the current tab
    31	            Navigation.isNavigationReady().then(() => {
    32	                Navigation.goBack();
    33	            });
    34	            return;
    35	        }
    36	        Session.initAutoAuthState(autoAuthState);
    37	
    38	        if (isSignedIn || (!login && !exitTo)) {
    39	            if (exitTo) {
    40	                Session.handleExitToNavigation(exitTo);
    41	            }
    42	            return;
    43	        }
    44	
    45	        // The user has initiated the sign in process on the same browser, in another tab.
    46	        Session.signInWithValidateCode(Number(accountID), validateCode);
    47	
    48	        // Since on Desktop we don't have multi-tab functionality to handle the login flow,
    49	        // we need to `popToTop` the stack after `signInWithValidateCode` in order to
    50	        // perform login for both 2FA and non-2FA accounts.
    51	        desktopLoginRedirect(autoAuthState, isSignedIn);
    52	        // eslint-disable-next-line react-compiler/react-compiler, react-hooks/exhaustive-deps
    53	    }, []);
    54	
    55	    useEffect(() => {
    56	        if (!!login || !cachedAccountID || !is2FARequired) {
    57	            if (exitTo) {
    58	                Session.handleExitToNavigation(exitTo);
    59	            }
    60	            return;
    61	        }
    62	
    63	        // The user clicked the option to sign in the current tab
    64	        Navigation.isNavigationReady().then(() => {
    65	            Navigation.goBack();
    66	        });
    67	    }, [login, cachedAccountID, is2FARequired, exitTo]);
    68	
    69	    return (
    70	        <>
    71	            {autoAuthState === CONST.AUTO_AUTH_STATE.FAILED && <ExpiredValidateCodeModal />}
    72	            {autoAuthState === CONST.AUTO_AUTH_STATE.SIGNING_IN && <FullScreenLoadingIndicator />}
    73	            {autoAuthState === CONST.AUTO_AUTH_STATE.JUST_SIGNED_IN && is2FARequired && !isSignedIn && <JustSignedInModal is2FARequired />}
    74	            {autoAuthState === CONST.AUTO_AUTH_STATE.JUST_SIGNED_IN && isSignedIn && !exitTo && <JustSignedInModal is2FARequired={false} />}
    75	            {autoAuthState === CONST.AUTO_AUTH_STATE.NOT_STARTED && !exitTo && (
    76	                <ValidateCodeModal
    77	                    accountID={Number(accountID)}
    78	                    code={validateCode}
    79	                />
    80	            )}
    81	            {autoAuthState !== CONST.AUTO_AUTH_STATE.FAILED && <FullScreenLoadingIndicator />}
    82	        </>
    83	    );
    84	}
    85	
    86	ValidateLoginPage.displayName = 'ValidateLoginPage';
    87	
    88	export default withOnyx<ValidateLoginPageProps<ValidateLoginPageOnyxProps>, ValidateLoginPageOnyxProps>({
    89	    account: {key: ONYXKEYS.ACCOUNT},
    90	    credentials: {key: ONYXKEYS.CREDENTIALS},
    91	    session: {key: ONYXKEYS.SESSION},
    92	})(ValidateLoginPage);
